  ('66b6dc4a-494c-5cad-a8a3-48c961eb9837'::uuid, 3, 3, 15, 50, 4,
   $ex${"titre":"Le héros qui obéit aux dieux","competence":"argumenter","situation":"Pour la dissertation, tu dois répondre : le héros d’une épopée cherche-t-il toujours la gloire ? Lis une scène écrite à la manière de Virgile, puis écoute deux élèves.","documents":[{"id":"depart","type":"texte","genre":"recit","titre":"Le départ de la plage","blocs":["Les dieux ont parlé. Le messager est reparti dans la nuit et la flotte attend sur la plage. Énée voit la reine qui l’implore ; son cœur se fend, et il obéit pourtant : l’avenir de son fils et de son peuple n’est pas à lui.","Il détourne les yeux, il fait lever l’ancre, et il emporte avec lui sa peine."],"source":"Texte écrit pour l’exercice, à la manière de l’Énéide de Virgile (aucune citation)"},{"id":"debat","type":"dialogue","titre":"Le débat","modele":"bulles","participants":[{"nom":"Léa","emoji":"👧","cote":"gauche"},{"nom":"Hugo","emoji":"👦","cote":"droite"}],"repliques":[{"qui":"Léa","texte":"Énée abandonne Didon : pour moi, ce n’est pas un héros, c’est un lâche."},{"qui":"Hugo","texte":"Virgile le montre fidèle à sa mission : il obéit aux dieux et pense à l’avenir de Rome."},{"qui":"Léa","texte":"Donc ce n’est pas la gloire personnelle qui le guide ?"},{"qui":"Hugo","texte":"Non. Ce qui le définit, c’est la pietas : le devoir envers les dieux, la patrie et la famille."}]}],"questions":[{"enonce":"Touche le verbe qui montre qu’Énée met le devoir avant son désir.","aide":"Qu’est-ce qu’il fait, malgré son cœur qui se fend ?","type":"zone","document":"depart","multiple":false},{"enonce":"Touche les deux mots qui disent au nom de qui Énée se sacrifie : sa famille et son peuple.","aide":"Cherche ce qui « n’est pas à lui ».","type":"zone","document":"depart","multiple":true},{"enonce":"Touche le mot latin qu’emploie Hugo pour nommer la vertu du héros virgilien.","aide":"C’est le mot qui est suivi de « le devoir envers les dieux, la patrie et la famille ».","type":"zone","document":"debat","multiple":false},{"enonce":"Relie chaque trait de l’*Énéide* à ce qu’il montre.","aide":"Pense à ce que le poème apporte à Rome, puis à ce qu’il apporte aux artistes qui suivent.","type":"association","gauche":[{"id":"g0","texte":"Une épopée nationale et politique"},{"id":"g1","texte":"Le pouvoir d’Auguste"},{"id":"g2","texte":"Un modèle absolu"},{"id":"g3","texte":"Didon et Énée"}],"droite":[{"id":"d0","texte":"Ils inspirent la tragédie, l’opéra, la peinture"},{"id":"d1","texte":"Elle donne à Rome une origine troyenne"},{"id":"d2","texte":"Il se trouve légitimé par cette origine"},{"id":"d3","texte":"Dante en fait son guide"}]}]}$ex$::jsonb,
   $ex$[{"cle":{"type":"zone","ids":["m31"]},"explication":"Énée **obéit** : malgré sa peine, il place l’ordre des dieux et l’avenir des siens au-dessus de lui."},{"cle":{"type":"zone","ids":["m37","m41"]},"explication":"Énée se sacrifie pour son **fils** (la famille) et son **peuple** (la patrie) : ce sont les deux cibles de la *pietas*."},{"cle":{"type":"zone","ids":["m52"]},"explication":"La vertu du héros est la ***pietas*** : le devoir envers les dieux, la patrie et la famille, et non la gloire personnelle."},{"cle":{"type":"association","paires":{"g3":"d0","g0":"d1","g1":"d2","g2":"d3"}},"explication":"L’épopée est **nationale et politique** : elle donne à Rome une origine troyenne et légitime le pouvoir d’Auguste ; elle devient un **modèle** (Dante) et nourrit les **réécritures**."}]$ex$::jsonb),
