   $ex${"titre":"Un philosophe, une marquise, un parc","competence":"se-reperer-temps","situation":"Tu prépares une fiche sur Fontenelle. Place les *Entretiens* dans sa vie, puis relève la carte d’identité de l’ouvrage.","documents":[{"id":"frise","type":"frise","titre":"Fontenelle et les Entretiens","debut":1650,"fin":1760,"pas":10,"evenements":[{"id":"z1","date":1657,"nom":"Naissance"},{"id":"z2","date":1686,"nom":"Les Entretiens"},{"id":"z3","date":1697,"nom":"Secrétaire perpétuel"},{"id":"z4","date":1757,"nom":"Mort"}]},{"id":"carte","type":"fiche","modele":"affiche","entete":"Entretiens sur la pluralité des mondes","sousTitre":"Fontenelle, 1686","emoji":"🔭","lignes":[{"texte":"Auteur","valeur":"Fontenelle, neveu de Corneille"},{"texte":"Forme","valeur":"Un dialogue en soirées","id":"z5"},{"texte":"Lieu","valeur":"Le parc d’un château"},{"texte":"Interlocutrice","valeur":"Une marquise"},{"texte":"Sujet","valeur":"Les mondes qui peuplent le ciel"}],"pied":"Un des premiers grands textes de vulgarisation scientifique","teinte":"violet"}],"questions":[{"enonce":"Sur la frise, touche l’année où paraissent les *Entretiens*.","aide":"C’est la date qui est dans le titre de la carte d’identité.","type":"zone","document":"frise","multiple":false},{"enonce":"Combien d’années s’écoulent entre la parution des *Entretiens* et la nomination de Fontenelle comme secrétaire perpétuel de l’Académie des sciences ?","aide":"Repère les deux dates sur la frise, puis soustrais.","type":"nombre","unite":"ans"},{"enonce":"Complète le résumé du dispositif.","aide":"Tout se trouve dans la carte d’identité : la forme, le lieu et le sujet.","type":"trous","segments":["Un ",0," s’entretient chaque soir avec une ",1," en regardant le ",2,"."],"banque":["marquise","jardin","reine","ciel","savant","philosophe"]}]}$ex$::jsonb,
