  ('a43e40cf-f35e-5b7a-b657-7fbe76a34874'::uuid, 2, 2, 10, 35, 4,
   $ex${"titre":"Les soleils de la marquise","competence":"analyser-texte","situation":"Ce soir-là, le philosophe a une idée à faire passer. Lis le résumé de la scène, puis le tableau qui dit ce que le livre bouscule.","documents":[{"id":"soir","type":"texte","genre":"recit","titre":"Un soir dans le parc","blocs":["Ce soir-là, le philosophe montre à la marquise une étoile et lui affirme qu’elle est un soleil, comme le nôtre, entouré peut-être de ses propres mondes.","Pour l’aider à comprendre, il compare l’univers à un opéra : le spectateur voit le spectacle, mais le philosophe cherche les machines cachées derrière le décor.","La marquise objecte, s’étonne, puis tire elle-même une conclusion : l’univers est bien plus grand qu’elle ne le pensait."],"source":"Résumé écrit pour l’exercice, d’après les Entretiens de Fontenelle"},{"id":"notions","type":"tableau","titre":"Ce que le livre bouscule","colonnes":["Notion","Ce qu’elle bouscule"],"lignes":[["Le système de Copernic","La Terre tourne autour du Soleil"],["La taille de l’univers","Elle dépasse l’imagination"],["La nature des planètes","Des mondes, non des points"],["Les étoiles fixes","Autant de soleils"]],"enteteLignes":true}],"questions":[{"enonce":"Touche le mot qui dit ce qu’est une étoile fixe, selon le philosophe.","aide":"Il la compare à notre propre astre.","type":"zone","document":"soir","multiple":false},{"enonce":"Dans l’image de l’opéra, que représentent les « machines cachées » derrière le décor ?","aide":"Le spectateur voit les effets ; que cherche le philosophe, lui ?","type":"choix","options":[{"id":"a","texte":"Les acteurs qui jouent devant la marquise"},{"id":"b","texte":"Les instruments que l’astronome pose sur le sol"},{"id":"c","texte":"Les spectateurs qui n’ont jamais vu le ciel"},{"id":"d","texte":"Les causes cachées des phénomènes que l’on observe"}],"multiple":false},{"enonce":"Dans le tableau, touche la case qui dit ce que bouscule le système de Copernic.","aide":"Cherche la première ligne du tableau.","type":"zone","document":"notions","multiple":false},{"enonce":"Complète ce que le dialogue permet.","aide":"Relis le résumé : la marquise objecte, s’étonne, conclut.","type":"trous","segments":["Le dialogue fait place aux ",0," et aux images ; la ",1," n’est pas une simple élève."],"banque":["objections","savants","sermons","marquise","dogmes"]}]}$ex$::jsonb,
   $ex$[{"cle":{"type":"zone","ids":["m17"]},"explication":"Pour le philosophe, chaque étoile fixe est un **soleil**, comme le nôtre."},{"cle":{"type":"choix","ids":["d"]},"explication":"Le spectateur ne voit que les **effets** ; le philosophe cherche les **causes cachées**, comme les machines qui manœuvrent derrière le décor."},{"cle":{"type":"zone","ids":["r0c1"]},"explication":"Le système de Copernic bouscule l’idée que le Soleil tourne autour de nous : c’est **la Terre qui tourne autour du Soleil**."},{"cle":{"type":"trous","trous":[["objections"],["marquise"]]},"affichage":"objections · marquise","explication":"Le dialogue permet les **objections** et les images ; la **marquise** pose les bonnes questions et tire parfois les conclusions avant le philosophe."}]$ex$::jsonb),
  ('a43e40cf-f35e-5b7a-b657-7fbe76a34874'::uuid, 3, 3, 15, 50, 5,
   $ex${"titre":"Galanterie ou science ?","competence":"argumenter","situation":"Un ton galant peut-il porter un savoir sérieux ? Écoute le débat de deux élèves, relis une phrase célèbre de l’ouvrage, puis construis ton argument.","documents":[{"id":"debat","type":"dialogue","titre":"Le débat","modele":"bulles","participants":[{"nom":"Inès","emoji":"👧","cote":"gauche"},{"nom":"Malo","emoji":"👦","cote":"droite"}],"repliques":[{"qui":"Inès","texte":"Ce ton de salon, c’est léger : ça nuit forcément à la rigueur de la science."},{"qui":"Malo","texte":"Au contraire. La galanterie est une stratégie : elle ouvre la science à ceux qui n’ont pas le latin."},{"qui":"Inès","texte":"Alors la marquise est juste un prétexte ?"},{"qui":"Malo","texte":"Non, elle pose les bonnes questions, et le lecteur avance avec elle."}]},{"id":"citation","type":"texte","genre":"source","titre":"Une phrase de l’ouvrage","blocs":["Toute la philosophie n’est fondée que sur deux choses, sur ce qu’on a l’esprit curieux et les yeux mauvais."],"source":"Fontenelle, Entretiens sur la pluralité des mondes (1686)"},{"id":"arg","type":"tableau","titre":"Un argument à compléter","colonnes":["Thèse","Argument","Exemple"],"lignes":[["La galanterie est une stratégie de diffusion","La science n’appartient pas aux seuls savants","?"],["Chaque notion se traduit en image","L’analogie vient du monde de l’interlocutrice","L’univers comparé à un opéra"]],"enteteLignes":true}],"questions":[{"enonce":"Touche le mot par lequel Malo définit la galanterie du ton.","aide":"Il répond à Inès qui parle de « ton léger ».","type":"zone","document":"debat","multiple":false},{"enonce":"Touche les deux qualités qui, selon la phrase, fondent toute philosophie.","aide":"L’une est de l’esprit, l’autre des yeux.","type":"zone","document":"citation","multiple":true},{"enonce":"Quel exemple faut-il écrire dans la case « ? » du tableau ?","aide":"L’exemple doit montrer la science ouverte à ceux qui n’en sont pas.","type":"choix","options":[{"id":"a","texte":"Un savant s’adresse à d’autres savants en latin"},{"id":"b","texte":"Un professeur donne un cours à l’Académie des sciences"},{"id":"c","texte":"Un marchand vend des instruments pour regarder le ciel"},{"id":"d","texte":"Une marquise, loin du latin et des académies, suit les leçons"}],"multiple":false},{"enonce":"Relie chaque procédé de l’ouvrage à son effet.","aide":"Pense à ce que chaque outil fait pour le lecteur.","type":"association","gauche":[{"id":"g0","texte":"Le dialogue en soirées"},{"id":"g1","texte":"Les images prises au monde mondain"},{"id":"g2","texte":"Le ton galant"},{"id":"g3","texte":"La conjecture raisonnable"}],"droite":[{"id":"d0","texte":"Rien n’est présenté comme dogme"},{"id":"d1","texte":"Une notion difficile devient accessible"},{"id":"d2","texte":"Le lecteur avance avec la marquise"},{"id":"d3","texte":"Il touche un public mondain, largement féminin"}]},{"enonce":"Quelle conclusion l’ouvrage permet-il le mieux d’appuyer en dissertation ?","aide":"Reviens à la thèse du tableau et à ce que dit Malo.","type":"choix","options":[{"id":"a","texte":"La rigueur scientifique interdit tout ton léger et toute image"},{"id":"b","texte":"Le ton galant peut servir à diffuser la science auprès de tous"},{"id":"c","texte":"Les femmes sont incapables de comprendre l’astronomie"},{"id":"d","texte":"La science se transmet seulement en latin devant des académies"}],"multiple":false}]}$ex$::jsonb,
   $ex$[{"cle":{"type":"zone","ids":["m22"]},"explication":"La galanterie est une **stratégie** de diffusion : elle sert à toucher un public mondain, exclu du latin."},{"cle":{"type":"zone","ids":["m17","m21"]},"explication":"La philosophie repose sur un esprit **curieux** et des yeux **mauvais** : on doute de ce qu’on voit et l’on cherche à savoir."},{"cle":{"type":"choix","ids":["d"]},"explication":"La **marquise** incarne ce public : elle n’a ni latin ni académie, et suit pourtant la science."},{"cle":{"type":"association","paires":{"g3":"d0","g1":"d1","g0":"d2","g2":"d3"}},"explication":"Le **dialogue** guide, les **images** traduisent, le **ton galant** élargit le public et la **conjecture** évite le dogme."},{"cle":{"type":"choix","ids":["b"]},"explication":"La galanterie est une **stratégie de diffusion** : l’ouvrage annonce les Lumières en ouvrant la science à tous."}]$ex$::jsonb),
