   $ex${"titre":"Un magistrat s’enferme dans sa tour","competence":"se-reperer-temps","situation":"Tu prépares ta fiche sur Montaigne. Place sa retraite dans sa vie, puis lis la carte d’identité des *Essais*.","documents":[{"id":"frise","type":"frise","titre":"La vie de Montaigne","debut":1530,"fin":1595,"pas":5,"evenements":[{"id":"z1","date":1533,"nom":"Naissance"},{"id":"z2","date":1571,"nom":"La tour"},{"id":"z3","date":1580,"nom":"Premiers Essais"},{"id":"z4","date":1592,"nom":"Mort"}]},{"id":"carte","type":"fiche","modele":"affiche","entete":"Essais","sousTitre":"Michel de Montaigne","emoji":"📚","lignes":[{"texte":"Livres","valeur":"Trois"},{"texte":"Première parution","valeur":"1580"},{"texte":"Édition posthume","valeur":"1595, par Marie de Gournay"},{"texte":"Le mot « essai »","valeur":"Une tentative, une pesée","id":"z5"}],"pied":"Augmentés jusqu’à la mort de l’auteur","teinte":"violet"}],"questions":[{"enonce":"Sur la frise, touche la date où Montaigne se retire dans sa tour.","aide":"Il quitte la magistrature pour sa bibliothèque.","type":"zone","document":"frise","multiple":false},{"enonce":"Quel âge Montaigne a-t-il quand il se retire dans sa tour ? (Compte avec les années de la frise.)","aide":"Soustrais la date de naissance à la date de la retraite.","type":"nombre","unite":"ans"},{"enonce":"Complète la phrase sur le titre de l’ouvrage.","aide":"Regarde la ligne « Le mot essai » de la carte d’identité.","type":"trous","segments":["Un « essai » est une ",0,", une pesée : Montaigne ne ",1," pas, il examine."],"banque":["tentative","décide","victoire","démontre","conclut"]}]}$ex$::jsonb,
