  ('fa754f80-2179-5b8a-9128-315aa8cb489a'::uuid, 2, 2, 10, 35, 4,
   $ex${"titre":"Je ne peins pas l’être, je peins le passage","competence":"analyser-texte","situation":"Pour comprendre la manière de Montaigne, lis un texte écrit à sa façon, puis le tableau des chapitres célèbres.","documents":[{"id":"manie","type":"texte","genre":"recit","titre":"À la manière de Montaigne","blocs":["Je voulais parler de la mémoire, et me voici à parler de mon chien. Qu’importe : ma pensée va où elle veut. J’ai essayé hier une opinion, je la corrige aujourd’hui ; je ne tiens rien pour sûr, et si l’on me presse, je réponds par ma devise."],"source":"Texte écrit pour l’exercice, à la manière des Essais (aucune citation)"},{"id":"chap","type":"tableau","titre":"Les chapitres à connaître","colonnes":["Chapitre","Ce qu’il énonce"],"lignes":[["De l’institution des enfants","Une éducation qui forme le jugement plutôt que la mémoire"],["De l’amitié","?"],["Des Cannibales","La barbarie est ce qui n’est pas de son usage"],["Des Coches","La destruction du Nouveau Monde"],["De l’expérience","Le corps, la vieillesse, la mesure"]],"enteteLignes":true}],"questions":[{"enonce":"Que dit le chapitre « De l’amitié », dont la case porte un « ? » ?","aide":"Souviens-toi de la formule « parce que c’était lui, parce que c’était moi ».","type":"choix","options":[{"id":"a","texte":"L’amitié s’apprend dans les livres des Anciens"},{"id":"b","texte":"Les amis doivent d’abord partager les mêmes opinions"},{"id":"c","texte":"L’amitié avec La Boétie s’explique par elle-même, sans raison"},{"id":"d","texte":"Un ami est utile quand il rend des services au magistrat"}],"multiple":false},{"enonce":"Touche la case qui dit ce que raconte le chapitre « Des Coches ».","aide":"Cherche la ligne « Des Coches ».","type":"zone","document":"chap","multiple":false},{"enonce":"Touche les deux verbes qui montrent que l’auteur revient sur sa propre pensée.","aide":"Il essaie une opinion un jour, puis la change.","type":"zone","document":"manie","multiple":true},{"enonce":"Range chaque geste : est-ce ce que fait Montaigne, ou ce qu’il ne fait pas ?","aide":"Pense à la méthode : refus des systèmes, doute, digressions.","type":"categories","categories":[{"id":"c0","texte":"Ce qu’il fait"},{"id":"c1","texte":"Ce qu’il ne fait pas"}],"items":[{"id":"i0","texte":"Écrire un traité systématique et ordonné"},{"id":"i1","texte":"Imposer une conclusion unique au lecteur"},{"id":"i2","texte":"Utiliser les citations antiques comme un matériau"},{"id":"i3","texte":"Ajouter des « allongeails » d’une édition à l’autre"},{"id":"i4","texte":"Passer d’un sujet à un autre par digressions"}]}]}$ex$::jsonb,
   $ex$[{"cle":{"type":"choix","ids":["c"]},"explication":"Montaigne explique son amitié avec La Boétie par la seule formule : « **parce que c’était lui, parce que c’était moi** »."},{"cle":{"type":"zone","ids":["r3c1"]},"explication":"« Des Coches » évoque la **destruction du Nouveau Monde**."},{"cle":{"type":"zone","ids":["m24","m30"]},"explication":"Il a **essayé** une opinion et la **corrige** : c’est le mouvement même de l’essai, qui examine et revient."},{"cle":{"type":"categories","items":{"i0":"c1","i1":"c1","i2":"c0","i3":"c0","i4":"c0"}},"explication":"Montaigne **digresse**, **ajoute** des allongeails et se sert des Anciens comme d’un **matériau** ; il ne construit ni **traité** ni **conclusion imposée**."}]$ex$::jsonb),
