   $ex${"titre":"Un poème pour la kôra","competence":"analyser-texte","situation":"Lis un poème écrit à la manière de Senghor, puis associe quelques poèmes du recueil à ce qu’ils célèbrent.","documents":[{"id":"pome","type":"texte","genre":"poeme","titre":"À la manière d’Éthiopiques","blocs":["(Pour kôra)","Je te salue, fleuve large comme une mère, toi qui portes nos ancêtres jusqu’à la mer ;","Je te salue, femme couleur de glaise, toi qui es terre et promesse à la fois.","Que le griot t’accompagne, que le tambour te réponde, et que la voix te dise."],"source":"Texte écrit pour l’exercice, à la manière de Senghor (aucune citation du poète)"},{"id":"themes","type":"tableau","titre":"Les thèmes du recueil","colonnes":["Thème","Ce qu’il porte"],"lignes":[["L’Afrique","Paysages, ancêtres, royaumes anciens, masques"],["La femme noire","?"],["L’exil en France","Le déchirement entre deux cultures"],["La réconciliation","Annoncée entre l’Afrique et l’Europe"]],"enteteLignes":true}],"questions":[{"enonce":"Touche le nom de l’instrument africain qui accompagne le poème, noté en tête.","aide":"Il est entre parenthèses, avant le premier vers.","type":"zone","document":"pome","multiple":false},{"enonce":"Touche les deux mots qui disent ce qu’est la femme dans ce poème.","aide":"Un mot du sol, un mot d’avenir.","type":"zone","document":"pome","multiple":true},{"enonce":"Que porte le thème de la femme noire, dont la case est un « ? » ?","aide":"Relis le poème que tu viens de lire : comment la femme y est-elle nommée ?","type":"choix","options":[{"id":"a","texte":"Elle est célébrée comme terre et comme promesse"},{"id":"b","texte":"Elle est le symbole de la ville d’acier"},{"id":"c","texte":"Elle est le témoin muet d’une défaite militaire"},{"id":"d","texte":"Elle est présentée comme une ennemie à fuir"}],"multiple":false},{"enonce":"Relie chaque titre à ce qu’il est ou à ce qu’il célèbre.","aide":"Chaque titre renvoie à un lieu, à un personnage ou à une postface.","type":"association","gauche":[{"id":"g0","texte":"Chaka"},{"id":"g1","texte":"À New York"},{"id":"g2","texte":"Congo"},{"id":"g3","texte":"Comme les lamantins vont boire à la source"}],"droite":[{"id":"d0","texte":"Le fleuve célébré comme une femme et une mère"},{"id":"d1","texte":"La postface où Senghor s’explique sur sa poétique"},{"id":"d2","texte":"Un poème pour orchestre de jazz qui oppose la ville d’acier à Harlem"},{"id":"d3","texte":"Un long poème dramatique sur le roi zoulou"}]}]}$ex$::jsonb,
