 à une ligne du tableau ou du cours.","type":"association","gauche":[{"id":"g0","texte":"Claudel et Saint-John Perse"},{"id":"g1","texte":"La négritude"},{"id":"g2","texte":"Le griot"},{"id":"g3","texte":"Chaka"}],"droite":[{"id":"d0","texte":"Le sommet du recueil, un long poème dramatique"},{"id":"d1","texte":"Modèles des versets amples"},{"id":"d2","texte":"Une parole dite et accompagnée"},{"id":"d3","texte":"Revendiquer une identité noire contre l’assimilation"}]},{"enonce":"Quelle conclusion de dissertation ce recueil permet-il le mieux d’appuyer ?","aide":"Relie l’engagement (la négritude) et le rythme (la voix).","type":"choix","options":[{"id":"a","texte":"La poésie doit rester neutre et se lire en silence"},{"id":"b","texte":"La poésie peut être engagée et lyrique, rythmée pour la voix"},{"id":"c","texte":"La poésie moderne a rompu avec la musique et la parole"},{"id":"d","texte":"La poésie est incompatible avec un engagement politique"}],"multiple":false}]}$ex$::jsonb,
