   $ex${"titre":"De l’or donné au crucifix convoité","competence":"se-reperer-temps","situation":"Pour ton oral, tu dois raconter l’histoire d’Eugénie en quatre étapes. Remets-les en ordre, puis relis la mort de Grandet.","documents":[{"id":"etapes","type":"tableau","titre":"Les étapes du roman (en désordre)","colonnes":["Étape","Ce qui se passe"],"lignes":[["Le retour","Sept ans plus tard, Charles revient riche, épouse une aristocrate et rompt par lettre"],["La fin","?"],["Le don","Eugénie donne en secret son or à Charles, qui part aux Indes"],["La punition","Grandet séquestre sa fille au pain et à l’eau : sa femme en meurt"]],"enteteLignes":true},{"id":"mort","type":"texte","genre":"recit","titre":"Sur le lit de mort","blocs":["Grandet est mourant. Le prêtre lui tend un crucifix de vermeil. Au lieu de prier, le vieil avare fait un geste terrible : il cherche à le saisir."],"source":"Résumé écrit pour l’exercice, d’après le roman de Balzac"}],"questions":[{"enonce":"Que devient Eugénie à la fin, case « ? » du tableau ?","aide":"Eugénie vit sans amour et se retrouve seule.","type":"choix","options":[{"id":"a","texte":"Elle quitte Saumur et fonde un couvent à Paris"},{"id":"b","texte":"Elle épouse sans amour le président de Bonfons"},{"id":"c","texte":"Elle perd sa fortune et sert chez les Cruchot"},{"id":"d","texte":"Elle épouse Charles et part avec lui aux Indes"}],"multiple":false},{"enonce":"Remets dans l’ordre les quatre étapes du roman.","aide":"Le don vient avant la punition qui le suit.","type":"ordre","items":[{"id":"a","texte":"Le retour"},{"id":"b","texte":"La fin"},{"id":"c","texte":"La punition"},{"id":"d","texte":"Le don"}]},{"enonce":"Touche l’objet que Grandet tente de saisir sur son lit de mort.","aide":"C’est ce que le prêtre lui tend.","type":"zone","document":"mort","multiple":false},{"enonce":"Que montre ce geste du vieillard mourant ?","aide":"Il a devant lui un objet de vermeil, qui brille.","type":"choix","options":[{"id":"a","texte":"Que Grandet rêve de partir aux Indes"},{"id":"b","texte":"Que Grandet veut rendre son or à sa fille"},{"id":"c","texte":"Que Grandet se convertit sincèrement"},{"id":"d","texte":"Que l’avarice le possède jusqu’à la mort"}],"multiple":false}]}$ex$::jsonb,
