   $ex${"titre":"La victime qui ressemble à son bourreau","competence":"analyser-texte","situation":"Pour la dissertation, tu veux montrer comment Balzac ouvre et ferme son roman. Lis deux phrases célèbres, relie des procédés à leurs effets, puis conclus.","documents":[{"id":"ouverture","type":"texte","genre":"recit","titre":"L’ouverture","blocs":["Certaines maisons de province inspirent « une mélancolie égale à celle que provoquent les cloîtres les plus sombres »."],"source":"Phrase de l’incipit : entre guillemets, Balzac, Eugénie Grandet (1833) ; le reste est résumé"},{"id":"fin","type":"texte","genre":"recit","titre":"La dernière page","blocs":["Telle est l’histoire de cette femme, qui n’est pas du monde au milieu du monde ; qui, faite pour être magnifiquement épouse et mère, n’a ni mari, ni enfants, ni famille."],"source":"Balzac, Eugénie Grandet (1833), dernière page"}],"questions":[{"enonce":"Touche le mot qui compare les maisons de province à des lieux de retrait du monde.","aide":"Pense à un lieu religieux, sombre et clos.","type":"zone","document":"ouverture","multiple":false},{"enonce":"Touche les trois mots qui disent ce qu’Eugénie n’a pas.","aide":"Une liste de trois termes après « ni ».","type":"zone","document":"fin","multiple":true},{"enonce":"Relie chaque élément du roman à ce qu’il montre.","aide":"Chaque élément renvoie à une idée de la fiche : argent, tragédie, destin, histoire.","type":"association","gauche":[{"id":"g0","texte":"L’argent"},{"id":"g1","texte":"Les pièces d’or et le morceau de sucre"},{"id":"g2","texte":"La fin du roman"},{"id":"g3","texte":"Les biens nationaux"}],"droite":[{"id":"d0","texte":"Un personnage qui structure la maison, la ville, le mariage, la piété"},{"id":"d1","texte":"La victime finit par ressembler à son bourreau"},{"id":"d2","texte":"L’origine révolutionnaire de la fortune de Grandet"},{"id":"d3","texte":"Une tragédie domestique bâtie à partir de presque rien"}]},{"enonce":"Quelle conclusion appuie le mieux les deux phrases lues ?","aide":"Compare le début (maisons-cloîtres) et la fin (ni mari, ni enfants).","type":"choix","options":[{"id":"a","texte":"Eugénie se révolte et fait détruire la maison"},{"id":"b","texte":"Eugénie finit comme son père, riche et seule"},{"id":"c","texte":"Eugénie quitte Saumur pour retrouver Charles"},{"id":"d","texte":"Eugénie finit heureuse, entourée de sa famille"}],"multiple":false}]}$ex$::jsonb,
