   $ex${"titre":"Le corbeau, le renard et le fromage","competence":"analyser-texte","situation":"Pour ton oral, tu veux commenter le début de « Le Corbeau et le Renard ». Lis les vers, puis le tableau des types d’animaux.","documents":[{"id":"vers","type":"texte","genre":"poeme","titre":"Le début de la fable","blocs":["Maître Corbeau, sur un arbre perché,","Tenait en son bec un fromage.","Maître Renard, par l’odeur alléché,","Lui tint à peu près ce langage :","Et bonjour, Monsieur du Corbeau."],"source":"La Fontaine, Fables, I, 2, « Le Corbeau et le Renard » (1668)"},{"id":"types","type":"tableau","titre":"Des types humains","colonnes":["Animal","Ce qu’il représente souvent"],"lignes":[["Le lion","Le roi, sa puissance et son arbitraire"],["Le renard","?"],["Le loup","La force brutale"],["L’agneau","La victime, le faible qu’on accable"]],"enteteLignes":true}],"questions":[{"enonce":"Touche le mot qui dit ce qui attire le renard vers le corbeau.","aide":"Le renard est sensible à une odeur.","type":"zone","document":"vers","multiple":false},{"enonce":"Ce que représente le renard, dont la case porte un « ? » ?","aide":"Dans les vers, que fait le renard pour obtenir le fromage ?","type":"choix","options":[{"id":"a","texte":"Le roi et son arbitraire"},{"id":"b","texte":"La force brutale qui écrase"},{"id":"c","texte":"La victime que l’on accable"},{"id":"d","texte":"Le courtisan rusé et flatteur"}],"multiple":false},{"enonce":"Remets dans l’ordre les trois moments de la scène.","aide":"Le renard n’agit qu’après avoir vu et senti le fromage.","type":"ordre","items":[{"id":"a","texte":"Le corbeau tient un fromage dans son bec"},{"id":"b","texte":"Le renard adresse la parole au corbeau"},{"id":"c","texte":"Le renard, attiré par l’odeur, s’approche"}]}]}$ex$::jsonb,
