  ('07ee1f70-87ea-558d-826c-e14e0a8c0475'::uuid, 3, 3, 15, 50, 5,
   $ex${"titre":"La raison du plus fort","competence":"argumenter","situation":"Deux élèves disent que les fables sont « pour les petits ». Lis deux textes de La Fontaine et réponds avec eux.","documents":[{"id":"loup","type":"texte","genre":"poeme","titre":"Le Loup et l’Agneau","blocs":["La raison du plus fort est toujours la meilleure :","Nous l’allons montrer tout à l’heure."],"source":"La Fontaine, Fables, I, 10, « Le Loup et l’Agneau » (1668), vers 1-2"},{"id":"peste","type":"texte","genre":"poeme","titre":"Les Animaux malades de la peste","blocs":["Selon que vous serez puissant ou misérable,","Les jugements de cour vous rendront blanc ou noir."],"source":"La Fontaine, Fables, VII, 1, « Les Animaux malades de la peste » (1678), derniers vers"},{"id":"debat","type":"dialogue","titre":"Le débat","modele":"bulles","participants":[{"nom":"Julie","emoji":"👧","cote":"gauche"},{"nom":"Karim","emoji":"👦","cote":"droite"}],"repliques":[{"qui":"Julie","texte":"Les Fables, c’est pour les enfants : des animaux qui parlent, rien de plus."},{"qui":"Karim","texte":"La Fontaine écrit pourtant : « Je me sers d’animaux pour instruire les hommes. »"},{"qui":"Julie","texte":"Instruire les hommes sur quoi ?"},{"qui":"Karim","texte":"Sur la cour, sur le pouvoir, sur la justice du plus fort."}]}],"questions":[{"enonce":"Touche le mot qui dit qui, selon la fable, a toujours raison.","aide":"Qui l’emporte dans « la raison du plus... » ?","type":"zone","document":"loup","multiple":false},{"enonce":"Touche les deux adjectifs qui s’opposent dans ces vers.","aide":"L’un dit le pouvoir, l’autre dit la faiblesse.","type":"zone","document":"peste","multiple":true},{"enonce":"Quel lien unit ces deux extraits ?","aide":"Dans chaque extrait, de quoi dépend le verdict : de la vérité ou du pouvoir ?","type":"choix","options":[{"id":"a","texte":"Dans les deux, le plus faible finit par triompher"},{"id":"b","texte":"Dans les deux, la force ou le rang l’emporte sur la justice"},{"id":"c","texte":"Dans les deux, l’auteur fait l’éloge de la cour"},{"id":"d","texte":"Dans les deux, la morale est absente du texte"}],"multiple":false},{"enonce":"Relie chaque animal au type humain qu’il représente.","aide":"Rappelle-toi que les animaux sont des types humains.","type":"association","gauche":[{"id":"g0","texte":"Le lion"},{"id":"g1","texte":"Le renard"},{"id":"g2","texte":"Le loup"},{"id":"g3","texte":"L’agneau"}],"droite":[{"id":"d0","texte":"Le courtisan rusé et flatteur"},{"id":"d1","texte":"La force brutale"},{"id":"d2","texte":"La victime que l’on accable"},{"id":"d3","texte":"Le roi, sa puissance et son arbitraire"}]},{"enonce":"Quelle conclusion de dissertation appuie le mieux ce dossier ?","aide":"Reprends la phrase de Karim : instruire les hommes sur quoi ?","type":"choix","options":[{"id":"a","texte":"Les Fables font l’éloge de la justice du plus fort"},{"id":"b","texte":"Les Fables ne s’adressent qu’aux enfants et n’ont aucune portée"},{"id":"c","texte":"Les Fables, sous leur apparence enfantine, satirisent la cour"},{"id":"d","texte":"Les Fables ont pour seul but de décrire des animaux"}],"multiple":false}]}$ex$::jsonb,
   $ex$[{"cle":{"type":"zone","ids":["m4"]},"explication":"C’est le plus **fort** qui a raison : la force fait la loi, avant toute justice."},{"cle":{"type":"zone","ids":["m4","m6"]},"explication":"Les jugements de cour dépendent du rang : **puissant** ou **misérable**."},{"cle":{"type":"choix","ids":["b"]},"explication":"Dans les deux textes, la **justice du plus fort** l’emporte : le jugement dépend du rang, non de la vérité."},{"cle":{"type":"association","paires":{"g1":"d0","g2":"d1","g3":"d2","g0":"d3"}},"explication":"Le **lion** est le roi, le **renard** le courtisan, le **loup** la force brutale, l’**agneau** la victime."},{"cle":{"type":"choix","ids":["c"]},"explication":"Sous l’apparence **enfantine**, les *Fables* sont une **satire de la cour** et une réflexion sur le pouvoir."}]$ex$::jsonb),
  ('e70c1290-bda0-50e8-a415-3960eb5ab28f'::uuid, 1, 1, 5, 20, 3,
   $ex${"titre":"Un intérieur nu, quatre personnages","competence":"analyser-document","situation":"Tu prépares ta fiche sur *Fin de partie*. Lis la carte d’identité de la pièce et le tableau des personnages, puis réponds.","documents":[{"id":"carte","type":"fiche","modele":"affiche","entete":"Fin de partie","sousTitre":"Samuel Beckett, 1957","emoji":"♟️","lignes":[{"texte":"Création","valeur":"1957, en français"},{"texte":"Mise en scène","valeur":"Roger Blin"},{"texte":"Succès précédent","valeur":"En attendant Godot (1953)","id":"z1"},{"texte":"Structure","valeur":"Un acte unique"},{"texte":"Courant","valeur":"Le théâtre de l’absurde","id":"z2"}],"pied":"Une pièce dépouillée, à l’humour noir","teinte":"violet"},{"id":"persos","type":"tableau","titre":"Les personnages","colonnes":["Personnage","Sa situation"],"lignes":[["Hamm","Aveugle et paralysé, dans un fauteuil à roulettes"],["Clov","?"],["Nagg et Nell","Les parents de Hamm, dans deux poubelles"]],"enteteLignes":true}],"questions":[{"enonce":"Touche la ligne qui dit à quel courant on rattache la pièce.","aide":"Beckett est rangé aux côtés de Ionesco.","type":"zone","document":"carte","multiple":false},{"enonce":"Combien d’années séparent *En attendant Godot* de *Fin de partie* ?","aide":"Repère les deux dates sur la carte d’identité, puis soustrais.","type":"nombre","unite":"ans"},{"enonce":"Quelle est la situation de Clov, dont la case porte un « ? » ?","aide":"Dans le tableau, Hamm est dans son fauteuil et Clov va et vient autour de lui.","type":"choix","options":[{"id":"a","texte":"Il est un médecin qui soigne les parents de Hamm"},{"id":"b","texte":"Il est un voisin qui vient raconter le monde du dehors"},{"id":"c","texte":"Il est le serviteur de Hamm : il ne peut pas s’asseoir ni partir"},{"id":"d","texte":"Il est le fils de Hamm, qui hérite de la maison"}],"multiple":false}]}$ex$::jsonb,
