g1","texte":"Les deux poubelles"},{"id":"g2","texte":"Les deux fenêtres hautes"},{"id":"g3","texte":"L’escabeau"}],"droite":[{"id":"d0","texte":"Clov, le serviteur"},{"id":"d1","texte":"Ce que Clov y voit : « zéro »"},{"id":"d2","texte":"Hamm, aveugle et paralysé"},{"id":"d3","texte":"Nagg et Nell, les parents de Hamm"}]},{"enonce":"Touche le dernier geste de la pièce.","aide":"C’est le geste de Hamm avec son mouchoir.","type":"zone","document":"jour","multiple":false}]}$ex$::jsonb,
