  ('e70c1290-bda0-50e8-a415-3960eb5ab28f'::uuid, 3, 3, 15, 50, 4,
   $ex${"titre":"Une fin de partie aux échecs","competence":"argumenter","situation":"Un sujet possible : le théâtre peut-il représenter le néant ? Écoute deux élèves, lis le tableau, puis construis ton argument.","documents":[{"id":"debat","type":"dialogue","titre":"Le débat","modele":"bulles","participants":[{"nom":"Léa","emoji":"👧","cote":"gauche"},{"nom":"Adam","emoji":"👦","cote":"droite"}],"repliques":[{"qui":"Léa","texte":"Un titre emprunté aux échecs pour une pièce sans intrigue : je ne vois pas le rapport."},{"qui":"Adam","texte":"Aux échecs, la fin de partie est le moment où l’issue est connue, mais où il faut continuer à jouer."},{"qui":"Léa","texte":"Donc la pièce joue un jeu dont on connaît déjà la fin ?"},{"qui":"Adam","texte":"Voilà : on répète les mêmes gestes en attendant que ça finisse."}]},{"id":"arg","type":"tableau","titre":"Un argument à compléter","colonnes":["Thèse","Argument","Exemple"],"lignes":[["La répétition remplace l’action","Les mêmes gestes, les mêmes demandes : le temps s’use","?"],["Les noms disent un couple qui frappe et qui subit","Hamm évoque le marteau, Clov, Nagg et Nell les clous","Hamm domine un serviteur et ses deux parents"]],"enteteLignes":true}],"questions":[{"enonce":"Touche le mot qui dit ce qui est déjà connu à la fin d’une partie d’échecs.","aide":"Elle est « connue » : de quoi s’agit-il ?","type":"zone","document":"debat","multiple":false},{"enonce":"Quel exemple faut-il écrire dans la case « ? » du tableau ?","aide":"Il s’agit d’un geste qui se répète sans jamais aboutir.","type":"choix","options":[{"id":"a","texte":"Clov trouve enfin un monde habité dehors"},{"id":"b","texte":"Hamm se lève de son fauteuil et sort"},{"id":"c","texte":"Nagg et Nell quittent leurs poubelles pour toujours"},{"id":"d","texte":"Clov menace de partir, et reste sur le seuil"}],"multiple":false},{"enonce":"Relie chaque procédé de la pièce à son effet.","aide":"Chaque procédé donne une impression au spectateur.","type":"association","gauche":[{"id":"g0","texte":"Un dialogue qui tourne en rond"},{"id":"g1","texte":"L’humour noir"},{"id":"g2","texte":"Un plateau presque vide"},{"id":"g3","texte":"Un titre venu des échecs"}],"droite":[{"id":"d0","texte":"Pas d’intrigue au sens classique"},{"id":"d1","texte":"Une scène intensément théâtrale"},{"id":"d2","texte":"L’issue est connue, il faut jouer"},{"id":"d3","texte":"On rit du malheur"}]},{"enonce":"Quelle conclusion de dissertation la pièce permet-elle le mieux d’appuyer ?","aide":"Reprends le sujet : le théâtre peut-il représenter le néant ?","type":"choix","options":[{"id":"a","texte":"Le théâtre ne peut pas se passer d’une intrigue complète"},{"id":"b","texte":"Le néant ne peut jamais être mis en scène"},{"id":"c","texte":"Un plateau presque vide peut être intensément théâtral"},{"id":"d","texte":"Le comique est incompatible avec le tragique"}],"multiple":false}]}$ex$::jsonb,
   $ex$[{"cle":{"type":"zone","ids":["m27"]},"explication":"À la fin de partie, l’**issue** est connue : il faut pourtant continuer à jouer, comme dans la pièce."},{"cle":{"type":"choix","ids":["d"]},"explication":"**Clov**, prêt à partir, **reste sur le seuil** : le geste annoncé n’aboutit jamais, la répétition remplace l’action."},{"cle":{"type":"association","paires":{"g0":"d0","g2":"d1","g3":"d2","g1":"d3"}},"explication":"Le **dialogue circulaire** supprime l’intrigue, l’**humour noir** fait rire du malheur, le **plateau vide** reste théâtral, le **titre** joue sur l’issue connue."},{"cle":{"type":"choix","ids":["c"]},"explication":"Beckett montre qu’un **plateau presque vide** peut être **intensément théâtral** : le néant se joue."}]$ex$::jsonb),
