  ('d07b76f6-1eb3-52fd-a2dd-9d3f835e48f4'::uuid, 2, 2, 10, 35, 4,
   $ex${"titre":"Deux manières d’éduquer un géant","competence":"analyser-texte","situation":"Gargantua a connu deux maîtres. Lis le tableau qui les compare, puis un résumé écrit pour l’exercice sur la méthode du second.","documents":[{"id":"maitres","type":"tableau","titre":"Deux éducations","colonnes":["Critère","Thubal Holoferne","Ponocrates"],"lignes":[["La méthode","Mémoire, latin, années perdues","Journée réglée, exercice physique, lectures commentées, observation directe"],["Le courant","La scolastique","?"]],"enteteLignes":true},{"id":"methode","type":"texte","genre":"recit","titre":"Une journée avec Ponocrates","blocs":["Quand Ponocrates prend Gargantua en main, tout change : la journée est réglée heure par heure. On lit, mais le maître commente chaque page. Puis on sort : le corps s’exerce autant que l’esprit, et l’on observe le monde autour de soi."],"source":"Résumé écrit pour l’exercice, d’après Gargantua de Rabelais"}],"questions":[{"enonce":"À quel courant Ponocrates appartient-il, case « ? » du tableau ?","aide":"Thubal est scolastique : Ponocrates est son contraire.","type":"choix","options":[{"id":"a","texte":"À l’humanisme"},{"id":"b","texte":"À la Sorbonne qui condamne les livres"},{"id":"c","texte":"À la scolastique"},{"id":"d","texte":"À l’abbaye de Thélème"}],"multiple":false},{"enonce":"Touche les trois verbes qui décrivent la méthode de Ponocrates.","aide":"Une journée, une lecture, un regard sur le monde.","type":"zone","document":"methode","multiple":true},{"enonce":"Range chaque trait : à quel maître appartient-il ?","aide":"Retourne au tableau : chaque colonne est un maître.","type":"categories","categories":[{"id":"c0","texte":"Thubal Holoferne"},{"id":"c1","texte":"Ponocrates"}],"items":[{"id":"i0","texte":"Les lectures commentées"},{"id":"i1","texte":"L’exercice physique"},{"id":"i2","texte":"La mémoire et le latin"},{"id":"i3","texte":"L’observation directe"},{"id":"i4","texte":"Les années perdues"}]},{"enonce":"Remets dans l’ordre les quatre grands moments du récit.","aide":"Le géant naît avant d’être éduqué et la guerre se règle avant la récompense.","type":"ordre","items":[{"id":"a","texte":"La guerre picrocholine éclate"},{"id":"b","texte":"Ponocrates réforme son éducation"},{"id":"c","texte":"L’abbaye de Thélème est offerte en récompense"},{"id":"d","texte":"Gargantua naît par l’oreille de sa mère"}]}]}$ex$::jsonb,
