   $ex${"titre":"Rire pour dire sérieusement","competence":"argumenter","situation":"Le rire de Rabelais est-il un simple divertissement ? Lis les vers d’avertissement, écoute un débat, puis construis ton argument.","documents":[{"id":"vers","type":"texte","genre":"poeme","titre":"Aux lecteurs","blocs":["Mieux est de ris que de larmes écrire,","Pour ce que rire est le propre de l’homme."],"source":"Rabelais, Gargantua (1534), « Aux lecteurs » (orthographe modernisée)"},{"id":"debat","type":"dialogue","titre":"Le débat","modele":"bulles","participants":[{"nom":"Paul","emoji":"👦","cote":"gauche"},{"nom":"Inès","emoji":"👧","cote":"droite"}],"repliques":[{"qui":"Paul","texte":"Rabelais veut seulement nous faire rire avec ses géants et ses banquets."},{"qui":"Inès","texte":"Son prologue invite à briser l’os pour en tirer la moelle : il y a un sens caché sous le comique."},{"qui":"Paul","texte":"Alors il faut chercher du sérieux partout ?"},{"qui":"Inès","texte":"Non : il se moque aussi de ceux qui cherchent trop loin."}]},{"id":"arg","type":"tableau","titre":"Un argument à compléter","colonnes":["Thèse","Argument","Exemple"],"lignes":[["Le rire est une méthode","Il désacralise la scolastique, la guerre de conquête et la religion formaliste","?"],["Thélème est une utopie élitiste","La liberté y suppose des gens bien nés, bien instruits","La règle « Fais ce que voudras »"]],"enteteLignes":true}],"questions":[{"enonce":"Touche le mot qui dit ce que le rire est pour l’homme.","aide":"Le rire n’appartient qu’à lui : il lui est...","type":"zone","document":"vers","multiple":false},{"enonce":"Touche le mot qui désigne le sens profond caché sous l’apparence comique.","aide":"On brise l’os pour en tirer la... quoi ?","type":"zone","document":"debat","multiple":false},{"enonce":"Quel exemple faut-il écrire dans la case « ? » du tableau ?","aide":"Cherche ce que le rire attaque : la scolastique, la guerre, la religion formaliste.","type":"choix","options":[{"id":"a","texte":"Le sage Grandgousier qui plaide la paix"},{"id":"b","texte":"La naissance de Gargantua en criant « À boire ! »"},{"id":"c","texte":"La règle de Thélème : « Fais ce que voudras »"},{"id":"d","texte":"Les années perdues de Thubal Holoferne, maître scolastique"}],"multiple":false},{"enonce":"Relie chaque élément de l’œuvre à ce qu’il montre.","aide":"Chaque élément renvoie à une ligne du tableau ou du cours.","type":"association","gauche":[{"id":"g0","texte":"Thélème"},{"id":"g1","texte":"La règle « Fais ce que voudras »"},{"id":"g2","texte":"La limite de Thélème"},{"id":"g3","texte":"Le prologue"}],"droite":[{"id":"d0","texte":"L’unique règle de l’abbaye"},{"id":"d1","texte":"Une utopie élitiste : bien nés, bien instruits"},{"id":"d2","texte":"Il compare le livre aux Silènes"},{"id":"d3","texte":"Un anti-monastère mixte, sans horloge"}]},{"enonce":"Quelle lecture du prologue le débat autorise-t-il ?","aide":"Reprends les deux répliques d’Inès.","type":"choix","options":[{"id":"a","texte":"Un sermon grave qui interdit de rire"},{"id":"b","texte":"Un livre sans aucun sens, écrit pour faire rire"},{"id":"c","texte":"Un sens profond sous le comique, sans chercher trop loin"},{"id":"d","texte":"Un traité de médecine déguisé en roman comique"}],"multiple":false}]}$ex$::jsonb,
