   $ex${"titre":"Du secret à la malédiction","competence":"analyser-document","situation":"Les événements de la pièce sont donnés en désordre. Rétablis leur suite, repère l’épisode de la tablette, puis montre que la parole peut tuer.","documents":[{"id":"temps","type":"tableau","titre":"Les six temps de la pièce (en désordre)","colonnes":["Temps","Ce qui arrive"],"lignes":[["La mort","Thésée maudit son fils ; un taureau surgi de la mer épouvante les chevaux, Hippolyte est traîné et brisé"],["La lutte","Phèdre se laisse mourir de faim plutôt que d’avouer"],["La fin","Artémis apparaît et révèle la vérité ; père et fils se réconcilient"],["La vengeance","Aphrodite inspire à Phèdre une passion pour son beau-fils"],["La calomnie","Phèdre se pend en laissant une tablette qui accuse faussement Hippolyte"],["La révélation","La nourrice révèle le secret à Hippolyte, qui la repousse avec horreur"]],"enteteLignes":true}],"questions":[{"enonce":"Remets les six temps de la pièce dans l’ordre.","aide":"La tablette suit la révélation ; la vérité n’éclate qu’à la toute fin.","type":"ordre","items":[{"id":"a","texte":"La révélation de la nourrice"},{"id":"b","texte":"La lutte de Phèdre"},{"id":"c","texte":"La calomnie de la tablette"},{"id":"d","texte":"La mort d’Hippolyte"},{"id":"e","texte":"L’apparition d’Artémis"},{"id":"f","texte":"La vengeance d’Aphrodite"}]},{"enonce":"Touche la case qui dit ce que contient la tablette laissée par Phèdre.","aide":"Cherche le temps où Phèdre se pend.","type":"zone","document":"temps","multiple":false},{"enonce":"Complète la phrase sur la parole dans la pièce.","aide":"Un mot dit la vérité qui blesse, un autre le mensonge, un dernier la mort.","type":"trous","segments":["La nourrice ",0," le secret, la tablette ",1,", la malédiction ",2,"."],"banque":["tue","cache","ment","révèle","chante"]},{"enonce":"Qui rétablit la vérité devant Thésée au dénouement ?","aide":"C’est la déesse que servait Hippolyte.","type":"choix","options":[{"id":"a","texte":"Aphrodite, qui avoue sa vengeance"},{"id":"b","texte":"Dionysos, dieu du concours tragique"},{"id":"c","texte":"Poséidon, qui regrette son geste"},{"id":"d","texte":"Artémis, protectrice d’Hippolyte"}],"multiple":false}]}$ex$::jsonb,
