   $ex${"titre":"Euripide ou Racine ?","competence":"argumenter","situation":"Comparer deux versions d’un même mythe est un exercice classique. Lis le tableau, puis un prologue écrit à la manière d’Euripide.","documents":[{"id":"comp","type":"tableau","titre":"Deux Phèdre","colonnes":["","Euripide, 428 av. J.-C.","Racine, 1677"],"lignes":[["Le cadre","Les dieux ouvrent et ferment l’action","Ils sont évoqués, non présents"],["Phèdre au moment de la vérité","?","Elle est vivante : c’est elle qui avoue"],["L’accent","La vengeance divine","?"]],"enteteLignes":true},{"id":"pro","type":"texte","genre":"theatre","titre":"Un prologue à la manière d’Euripide","blocs":[{"personnage":"Aphrodite","replique":"Ceux qui m’honorent, je les élève ; ceux qui me méprisent, je les abats. Hippolyte, fils de Thésée, ne sert que la chaste Artémis."},{"didascalie":"La déesse regarde vers le palais de Trézène."}],"source":"Texte écrit pour l’exercice, à la manière d’Euripide"}],"questions":[{"enonce":"Que faut-il écrire dans la case « ? » pour Phèdre chez Euripide ?","aide":"Chez Racine elle est vivante : qu’en est-il chez Euripide ?","type":"choix","options":[{"id":"a","texte":"Elle est sauvée par Artémis au dernier instant"},{"id":"b","texte":"Elle s’enfuit de Trézène avec Hippolyte"},{"id":"c","texte":"Elle est déjà morte quand la vérité éclate"},{"id":"d","texte":"Elle avoue elle-même et supplie Thésée"}],"multiple":false},{"enonce":"Quel accent met Racine, d’après la dernière ligne du tableau ?","aide":"C’est ce qui change quand les dieux ne sont plus sur scène.","type":"choix","options":[{"id":"a","texte":"La vengeance divine"},{"id":"b","texte":"Le hasard du destin"},{"id":"c","texte":"La force de la nature"},{"id":"d","texte":"La conscience coupable"}],"multiple":false},{"enonce":"Touche le nom de la déesse que sert Hippolyte.","aide":"Aphrodite en parle comme de sa rivale.","type":"zone","document":"pro","multiple":false},{"enonce":"Que montre cette comparaison sur la réécriture d’un mythe ?","aide":"Compare ce qui compte pour chacun : les dieux ou la conscience.","type":"choix","options":[{"id":"a","texte":"Racine recopie fidèlement Euripide pour respecter l’Antiquité"},{"id":"b","texte":"Un mythe ne peut être raconté que dans sa première forme"},{"id":"c","texte":"La réécriture supprime toujours les personnages d’origine"},{"id":"d","texte":"Reprendre un mythe, c’est en déplacer le centre, du divin vers la conscience"}],"multiple":false}]}$ex$::jsonb,
