   $ex${"titre":"La route de Londres","competence":"analyser-texte","situation":"Chassé de chez son protecteur, Tom prend la route. Lis le résumé, puis range ceux qui font semblant d’être vertueux et ceux qui ont du cœur.","documents":[{"id":"resume","type":"texte","genre":"recit","titre":"Le fil du roman","blocs":["Calomnié par Blifil, Tom est chassé de la maison d’Allworthy. Il prend la route de Londres, où l’attendent auberges, duels, rencontres et prison.","De son côté, Sophia s’est enfuie de chez son père pour ne pas épouser Blifil. Au dénouement, on découvre la naissance de Tom : il est le fils de la sœur d’Allworthy."],"source":"Résumé écrit pour l’exercice, d’après le cours"},{"id":"etapes","type":"chaine","titre":"Les grandes étapes","disposition":"colonne","noeuds":[{"id":"z1","texte":"Blifil calomnie Tom"},{"id":"z2","texte":"?"},{"id":"z3","texte":"Tom prend la route de Londres"},{"id":"z4","texte":"La naissance de Tom est révélée"},{"id":"z5","texte":"Tom épouse Sophia"}],"liens":[{"de":"z1","a":"z2"},{"de":"z2","a":"z3"},{"de":"z3","a":"z4"},{"de":"z4","a":"z5"}]}],"questions":[{"enonce":"Touche le mot qui dit par où Tom quitte la maison d’Allworthy.","aide":"Un chemin, vers la capitale.","type":"zone","document":"resume","multiple":false},{"enonce":"Touche le verbe qui dit ce que fait Sophia pour échapper à Blifil.","aide":"Elle quitte la maison de son père.","type":"zone","document":"resume","multiple":false},{"enonce":"Quelle étape manque dans la chaîne (la case « ? ») ?","aide":"Entre la calomnie et le départ sur la route, il y a une sanction.","type":"choix","options":[{"id":"a","texte":"Tom est chassé de la maison d’Allworthy"},{"id":"b","texte":"Tom est reconnu fils du squire Western"},{"id":"c","texte":"Sophia retrouve Tom à Londres"},{"id":"d","texte":"Partridge révèle la naissance de Tom"}],"multiple":false},{"enonce":"Range chaque personnage : vertu d’apparence ou bonté du cœur ?","aide":"Les deux précepteurs sont, comme Blifil, hypocrites.","type":"categories","categories":[{"id":"c0","texte":"Vertu d’apparence"},{"id":"c1","texte":"Bonté du cœur"}],"items":[{"id":"i0","texte":"Sophia Western"},{"id":"i1","texte":"Le squire Allworthy"},{"id":"i2","texte":"Blifil"},{"id":"i3","texte":"Thwackum"},{"id":"i4","texte":"Tom Jones"},{"id":"i5","texte":"Square"}]}]}$ex$::jsonb,
   $ex$[{"cle":{"type":"zone","ids":["m14"]},"explication":"Tom prend **la route** de Londres : c’est le roman de voyage, avec ses méprises et ses rencontres."},{"cle":{"type":"zone","ids":["m31"]},"explication":"Sophia **s’enfuit** de chez son père : elle refuse d’épouser Blifil."},{"cle":{"type":"choix","ids":["a"]},"explication":"La calomnie de Blifil mène à l’étape manquante : **Tom est chassé** de la maison d’Allworthy."},{"cle":{"type":"categories","items":{"i0":"c1","i1":"c1","i2":"c0","i3":"c0","i4":"c1","i5":"c0"}},"explication":"**Blifil**, **Thwackum** et **Square** jouent la vertu ; **Tom**, **Allworthy** et **Sophia** ont du cœur. Pour Fielding, la vertu est la bonté du cœur."}]$ex$::jsonb),
  ('a3a19d77-ce35-5593-95b4-25e0afbdaf9f'::uuid, 3, 3, 15, 50, 4,
   $ex${"titre":"Un narrateur qui sert le repas","competence":"argumenter","situation":"Chaque livre de *Tom Jones* s’ouvre par un chapitre où l’auteur parle au lecteur. Lis un pastiche, puis tranche un débat sur la vertu.","documents":[{"id":"pref","type":"texte","genre":"recit","titre":"Un chapitre-préface à la manière de Fielding","blocs":["Que le lecteur ne se plaigne pas du menu : je suis, en ces pages, comme un aubergiste qui sert à ses hôtes le repas qu’il a lui-même préparé.","Je n’y mets que de la nature humaine, avec ses vertus mal habillées et ses vices bien tenus. Si un plat vous déplaît, n’en dégoûtez pas votre voisin."],"source":"Texte écrit pour l’exercice, à la manière de Fielding"},{"id":"deb","type":"dialogue","titre":"Le débat","modele":"bulles","participants":[{"nom":"Élodie","emoji":"👧","cote":"gauche"},{"nom":"Mehdi","emoji":"👦","cote":"droite"}],"repliques":[{"qui":"Élodie","texte":"Tom est impulsif et sensuel : ce n’est pas un modèle de vertu."},{"qui":"Mehdi","texte":"Blifil est irréprochable en public : c’est lui le vrai vertueux."},{"qui":"Élodie","texte":"Alors la vertu, ce serait l’apparence ?"},{"qui":"Mehdi","texte":"Non : pour Fielding, la vertu est la bonté du cœur, pas la pureté sans faute."}]}],"questions":[{"enonce":"Touche le mot par lequel le narrateur s’adresse directement à son public.","aide":"Il parle à celui qui lit le livre.","type":"zone","document":"pref","multiple":false},{"enonce":"Touche le mot qui donne l’image à laquelle le narrateur se compare.","aide":"Quelqu’un qui sert un repas à ses hôtes.","type":"zone","document":"pref","multiple":false},{"enonce":"Quelle lecture de la morale du roman le dialogue permet-il de défendre ?","aide":"Relis la dernière réplique de Mehdi.","type":"choix","options":[{"id":"a","texte":"Le vice est toujours puni dès les premiers livres du roman"},{"id":"b","texte":"La naissance décide seule de la valeur d’un homme"},{"id":"c","texte":"La vertu est la bonté du cœur, non la pureté sans faute"},{"id":"d","texte":"La vertu est l’apparence irréprochable aux yeux du monde"}],"multiple":false},{"enonce":"Relie chaque trait du roman à son effet.","aide":"Chaque procédé a une conséquence sur la lecture.","type":"association","gauche":[{"id":"g0","texte":"Narrateur omniprésent et ironique"},{"id":"g1","texte":"Un chapitre-préface en tête de chaque livre"},{"id":"g2","texte":"Une intrigue d’horlogerie"},{"id":"g3","texte":"Blifil face à Tom"}],"droite":[{"id":"d0","texte":"Tout se recolle à la fin"},{"id":"d1","texte":"L’auteur discute de l’art du roman"},{"id":"d2","texte":"Le lecteur est pris à témoin"},{"id":"d3","texte":"La vertu d’apparence s’oppose à la bonté imparfaite"}]}]}$ex$::jsonb,
   $ex$[{"cle":{"type":"zone","ids":["m2"]},"explication":"Le narrateur interpelle **le lecteur** : il est « intrusif », ce qui est la marque de Fielding."},{"cle":{"type":"zone","ids":["m16"]},"explication":"Le narrateur se compare à **un aubergiste** qui sert à ses lecteurs le repas qu’il a préparé."},{"cle":{"type":"choix","ids":["c"]},"explication":"Le roman défend l’idée que **la vertu est la bonté du cœur**, non la pureté sans faute : Tom, imparfait, vaut mieux que Blifil."},{"cle":{"type":"association","paires":{"g2":"d0","g1":"d1","g0":"d2","g3":"d3"}},"explication":"L’**ironie** prend le lecteur à témoin, les **chapitres-préfaces** parlent du roman, l’**horlogerie** recolle l’intrigue, l’**opposition** Blifil / Tom porte la morale."}]$ex$::jsonb),
  ('e895e440-fb5b-5d3a-81c7-c29d66b08dec'::uuid, 1, 1, 5, 20, 4,
   $ex${"titre":"Un souvenir de quarante ans","competence":"se-reperer-temps","situation":"Tu présentes à l’oral un livre de souvenirs sur la jeunesse romantique. Place-le dans la vie de son auteur et dans l’histoire du mouvement.","documents":[{"id":"frise","type":"frise","titre":"Gautier et la bataille romantique","debut":1810,"fin":1880,"pas":10,"evenements":[{"id":"z1","date":1811,"nom":"Naissance"},{"id":"z2","date":1830,"nom":"Bataille d’Hernani"},{"id":"z3","date":1872,"nom":"Mort de Gautier"},{"id":"z4","date":1874,"nom":"Publication"}]},{"id":"fiche","type":"fiche","modele":"affiche","entete":"Histoire du romantisme","sousTitre":"Théophile Gautier","emoji":"🧣","lignes":[{"id":"z5","texte":"Nature","valeur":"Un témoignage de participant"},{"id":"z6","texte":"Écrit","valeur":"Quarante ans après les faits"},{"id":"z7","texte":"Épisode célèbre","valeur":"?"}],"pied":"Livre de souvenirs, inachevé","teinte":"violet"}],"questions":[{"enonce":"Sur la frise, touche l’année où le livre paraît.","aide":"Le livre est publié après la mort de l’auteur.","type":"zone","document":"frise","multiple":false},{"enonce":"Combien d’années séparent la bataille d’*Hernani* de la mort de Gautier ?","aide":"Lis les deux dates sur la frise et soustrais.","type":"nombre","unite":"ans"},{"enonce":"Quel épisode célèbre faut-il écrire dans la case « ? » de la fiche ?","aide":"C’est le jour où le romantisme livre bataille au théâtre, en 1830.","type":"choix","options":[{"id":"a","texte":"La publication des *Fleurs du mal*"},{"id":"b","texte":"La mort de Victor Hugo en 1885"},{"id":"c","texte":"La première d’*Hernani* et le gilet rouge"},{"id":"d","texte":"Le sacre de Napoléon III"}],"multiple":false},{"enonce":"Complète avec la fiche.","aide":"Ce n’est pas une histoire savante.","type":"trous","segments":["Le livre est un ",0," de participant, écrit ",1," ans après les faits."],"banque":["vingt","témoignage","quarante","dix","essai"]}]}$ex$::jsonb,
