   $ex${"titre":"Gilet rouge ou pourpoint de satin cerise ?","competence":"argumenter","situation":"Le romantisme est-il d’abord une révolution littéraire ou un mouvement de jeunesse ? Lis un débat, puis la formule la plus célèbre de Gautier.","documents":[{"id":"deb","type":"dialogue","titre":"Le débat","modele":"bulles","participants":[{"nom":"Nina","emoji":"👧","cote":"gauche"},{"nom":"Tom","emoji":"👦","cote":"droite"}],"repliques":[{"qui":"Nina","texte":"Le gilet rouge de Gautier, c’est de la provocation pure."},{"qui":"Tom","texte":"Lui-même corrige la légende : c’était un pourpoint de satin cerise, taillé exprès pour la première."},{"qui":"Nina","texte":"Donc il se déguisait pour choquer."},{"qui":"Tom","texte":"Il montre surtout que le romantisme est un mouvement de jeunesse autant qu’une révolution littéraire."}]},{"id":"formule","type":"texte","genre":"source","titre":"Une formule célèbre","blocs":["Il n’y a de vraiment beau que ce qui ne peut servir à rien ; tout ce qui est utile est laid."],"source":"Théophile Gautier, préface de *Mademoiselle de Maupin* (1835)"}],"questions":[{"enonce":"Touche les deux mots que Gautier oppose.","aide":"L’un décrit ce qui est inutile, l’autre ce qui sert.","type":"zone","document":"formule","multiple":true},{"enonce":"Quelle doctrine cette phrase annonce-t-elle ?","aide":"Elle sépare le beau de tout usage.","type":"choix","options":[{"id":"a","texte":"Le réalisme, qui copie la vie sociale de son temps"},{"id":"b","texte":"Le classicisme, qui impose les règles anciennes"},{"id":"c","texte":"L’art pour l’art, qui refuse toute utilité à la beauté"},{"id":"d","texte":"L’art engagé, au service d’une cause politique"}],"multiple":false},{"enonce":"Que prouve la réplique de Tom sur le pourpoint de satin cerise ?","aide":"Le gilet « rouge » est devenu une légende.","type":"choix","options":[{"id":"a","texte":"Que le vêtement n’avait aucune importance pour le groupe"},{"id":"b","texte":"Que Gautier corrige lui-même la légende du gilet rouge"},{"id":"c","texte":"Que le romantisme n’a jamais provoqué la moindre dispute"},{"id":"d","texte":"Que Gautier n’a jamais assisté à la première d’*Hernani*"}],"multiple":false},{"enonce":"Range chaque élément : le romantique de 1830 ou l’auteur de l’art pour l’art ?","aide":"Les pièces écrites en 1830 sont des souvenirs de jeunesse.","type":"categories","categories":[{"id":"c0","texte":"En 1830"},{"id":"c1","texte":"Plus tard"}],"items":[{"id":"i0","texte":"Le romantique en gilet rouge"},{"id":"i1","texte":"*Émaux et Camées*"},{"id":"i2","texte":"Une doctrine qui annonce le Parnasse"},{"id":"i3","texte":"La bataille d’*Hernani*"},{"id":"i4","texte":"La préface de *Mademoiselle de Maupin*"}]}]}$ex$::jsonb,
